using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using IdleRestaurant;
public static class RestaurantProductionBuilder {
 public const string CatalogPath="Assets/Restaurant/Production/Data/RestaurantCatalog.asset";
 [Serializable] class Import {public OutletDefinition[] outlets;public ResearchDefinition[] research;public ManagerDefinition[] managers;}
 [MenuItem("Restaurant/Production/Import Reference Catalog")]
 public static void ImportCatalog(){var data=Newtonsoft.Json.JsonConvert.DeserializeObject<Import>(File.ReadAllText("Design/CatalogImport.json"));var catalog=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(CatalogPath);if(!catalog){catalog=ScriptableObject.CreateInstance<RestaurantCatalog>();AssetDatabase.CreateAsset(catalog,CatalogPath);}catalog.outlets=data.outlets;catalog.research=data.research;catalog.managers=data.managers;catalog.maxRank=0;catalog.musicClip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Restaurant/Production/Audio/CozyMarimba.wav");catalog.coinClip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Restaurant/Production/Audio/Coin.wav");catalog.tapClip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Restaurant/Production/Audio/Tap.wav");catalog.upgradeClip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Restaurant/Production/Audio/Upgrade.wav");catalog.musicVolume=.4f;for(int i=0;i<catalog.outlets.Length;i++){catalog.outlets[i].environment=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Restaurant/Production/Art/Outlet"+i.ToString("00")+".prefab");catalog.outlets[i].food=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Restaurant/Production/Art/SignatureFood"+i+".prefab");}EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();Debug.Log("RESTAURANT_CATALOG_IMPORTED 40 outlets / 71 managers / 17 research");}
 [MenuItem("Restaurant/Production/Create Playable Scene")]
 public static void Prepare(){
  if(EditorApplication.isPlaying)throw new InvalidOperationException("Exit Play mode before scene authoring");if(!AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(CatalogPath))ImportCatalog();
  var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var background=new GameObject("Full-screen background",typeof(Camera)).GetComponent<Camera>();background.depth=-10;background.cullingMask=0;background.clearFlags=CameraClearFlags.SolidColor;background.backgroundColor=new Color(.98f,.96f,.91f);var camera=new GameObject("Main Camera",typeof(Camera),typeof(AudioListener)).GetComponent<Camera>();camera.tag="MainCamera";camera.orthographic=true;camera.orthographicSize=7.2f;camera.transform.position=new Vector3(8,15,-17);camera.transform.LookAt(new Vector3(0,.5f,.6f));camera.rect=new Rect(0,.32f,1,.4f);camera.backgroundColor=new Color(.94f,.9f,.81f);camera.clearFlags=CameraClearFlags.SolidColor;camera.allowHDR=false;
  var camdata=camera.GetUniversalAdditionalCameraData();camdata.renderPostProcessing=true;camdata.antialiasing=AntialiasingMode.SubpixelMorphologicalAntiAliasing;camdata.antialiasingQuality=AntialiasingQuality.Low;
  var light=new GameObject("Afternoon sunlight",typeof(Light)).GetComponent<Light>();light.type=LightType.Directional;light.intensity=1.5f;light.color=new Color(1,.94f,.83f);light.transform.rotation=Quaternion.Euler(50,-30,0);light.shadows=LightShadows.Soft;light.shadowStrength=.35f;
  RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.84f,.9f,.85f);RenderSettings.ambientEquatorColor=new Color(.72f,.78f,.7f);RenderSettings.ambientGroundColor=new Color(.58f,.60f,.53f);RenderSettings.skybox=null;
  var volume=new GameObject("Cozy food grade",typeof(Volume)).GetComponent<Volume>();volume.isGlobal=true;volume.sharedProfile=AssetDatabase.LoadAssetAtPath<VolumeProfile>("Assets/Restaurant/CozyGrade.asset");
  var app=new GameObject("Idle Restaurant Game",typeof(RestaurantApp)).GetComponent<RestaurantApp>();app.catalog=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(CatalogPath);app.gameCamera=camera;app.world=new GameObject("Restaurant world",typeof(RestaurantWorld)).GetComponent<RestaurantWorld>();app.world.catalog=app.catalog;
  PlayerSettings.productName="Idle Restaurant Tycoon";PlayerSettings.companyName="Mahnul";PlayerSettings.SetApplicationIdentifier(BuildTargetGroup.Android,"com.mahnul.idlerestaurant");PlayerSettings.Android.minSdkVersion=AndroidSdkVersions.AndroidApiLevel30;PlayerSettings.Android.targetSdkVersion=AndroidSdkVersions.AndroidApiLevelAuto;PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android,ScriptingImplementation.IL2CPP);PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;PlayerSettings.defaultInterfaceOrientation=UIOrientation.Portrait;PlayerSettings.allowedAutorotateToLandscapeLeft=false;PlayerSettings.allowedAutorotateToLandscapeRight=false;PlayerSettings.runInBackground=false;PlayerSettings.bundleVersion="0.5.3";PlayerSettings.Android.bundleVersionCode=10;
  EditorSceneManager.SaveScene(scene,"Assets/Restaurant/Production/RestaurantGame.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene("Assets/Restaurant/Production/RestaurantGame.unity",true)};AssetDatabase.SaveAssets();RestaurantFilmBuilder.Portrait();Debug.Log("RESTAURANT_PLAYABLE_SCENE_READY");
 }
 [MenuItem("Restaurant/Production/Build Android APK")]
 public static void BuildAndroid(){Directory.CreateDirectory("Builds");var options=new BuildPlayerOptions{scenes=new[]{"Assets/Restaurant/Production/RestaurantGame.unity"},locationPathName="Builds/IdleRestaurant-Android.apk",target=BuildTarget.Android,options=BuildOptions.None};EditorUserBuildSettings.buildAppBundle=false;var result=BuildPipeline.BuildPlayer(options);Debug.Log("RESTAURANT_BUILD "+result.summary.result+" errors="+result.summary.totalErrors+" bytes="+result.summary.totalSize);}
 [MenuItem("Restaurant/Production/Bake Characters and Food")]
 public static void BakeActors(){
  var catalog=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(CatalogPath);string folder="Assets/Restaurant/Production/Art";
  for(int i=0;i<3;i++){var holder=new GameObject("Bake holder");var actor=new RestaurantPreview.Person(holder.transform,Vector3.zero,i==0?"#75AAA1":"#FFF3DD","#64503F",i==1,i==2);actor.root.name=i==0?"Guest":i==1?"Chef":"Host";var rig=actor.root.gameObject.AddComponent<RestaurantActorRig>();rig.body=actor.body;rig.head=actor.head;rig.leftArm=actor.leftArm;rig.rightArm=actor.rightArm;rig.leftLeg=actor.leftLeg;rig.rightLeg=actor.rightLeg;rig.tray=actor.tray;PersistGenerated(actor.root.gameObject,folder+"/Character"+i+".asset");var prefab=PrefabUtility.SaveAsPrefabAsset(actor.root.gameObject,folder+"/Character"+i+".prefab");if(i==0)catalog.guestPrefab=prefab;else if(i==1)catalog.chefPrefab=prefab;else catalog.hostPrefab=prefab;UnityEngine.Object.DestroyImmediate(holder);}
  for(int i=0;i<40;i++){var holder=new GameObject("Bake holder");var food=RestaurantFoodArt.Create(holder.transform,Vector3.zero,i);PersistGenerated(food.gameObject,folder+"/SignatureFood"+i+".asset");catalog.outlets[i].food=PrefabUtility.SaveAsPrefabAsset(food.gameObject,folder+"/SignatureFood"+i+".prefab");UnityEngine.Object.DestroyImmediate(holder);}EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();Debug.Log("RESTAURANT_REPLACEABLE_ACTORS_READY");
 }
 static void PersistGenerated(GameObject root,string path){var bundle=AssetDatabase.LoadAssetAtPath<RestaurantArtBundle>(path);if(!bundle){bundle=ScriptableObject.CreateInstance<RestaurantArtBundle>();AssetDatabase.CreateAsset(bundle,path);}var objects=new System.Collections.Generic.HashSet<UnityEngine.Object>();foreach(var f in root.GetComponentsInChildren<MeshFilter>())if(f.sharedMesh&&!AssetDatabase.Contains(f.sharedMesh)&&objects.Add(f.sharedMesh))AssetDatabase.AddObjectToAsset(f.sharedMesh,bundle);foreach(var r in root.GetComponentsInChildren<Renderer>())if(r.sharedMaterial&&!AssetDatabase.Contains(r.sharedMaterial)&&objects.Add(r.sharedMaterial))AssetDatabase.AddObjectToAsset(r.sharedMaterial,bundle);AssetDatabase.SaveAssets();}
 [MenuItem("Restaurant/Production/Bake District Prefabs")]
 public static void BakeEnvironments(){BakeEnvironmentRange(0,40);}
 public static void BakeEnvironmentRange(int first,int end){
  var catalog=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(CatalogPath);var folder="Assets/Restaurant/Production/Art";Directory.CreateDirectory(folder);AssetDatabase.Refresh();
  for(int i=first;i<end;i++){var root=new GameObject(catalog.outlets[i].title);RestaurantWorld.BuildEnvironment(root.transform,i/8,i%8);RestaurantWorld.CombineStatic(root.transform);
   // Persist generated meshes and materials before saving the replaceable prefab.
   string path=folder+"/Outlet"+i.ToString("00")+".asset";var container=AssetDatabase.LoadAssetAtPath<RestaurantArtBundle>(path);if(!container){container=ScriptableObject.CreateInstance<RestaurantArtBundle>();AssetDatabase.CreateAsset(container,path);}var meshes=new System.Collections.Generic.HashSet<Mesh>();var materials=new System.Collections.Generic.HashSet<Material>();foreach(var f in root.GetComponentsInChildren<MeshFilter>())if(f.sharedMesh&&!AssetDatabase.Contains(f.sharedMesh)&&meshes.Add(f.sharedMesh))AssetDatabase.AddObjectToAsset(f.sharedMesh,container);foreach(var r in root.GetComponentsInChildren<Renderer>())if(r.sharedMaterial&&!AssetDatabase.Contains(r.sharedMaterial)&&materials.Add(r.sharedMaterial))AssetDatabase.AddObjectToAsset(r.sharedMaterial,container);AssetDatabase.SaveAssets();catalog.outlets[i].environment=PrefabUtility.SaveAsPrefabAsset(root,folder+"/Outlet"+i.ToString("00")+".prefab");UnityEngine.Object.DestroyImmediate(root);
  }EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();Debug.Log("RESTAURANT_ART_BAKED 40 replaceable environment prefabs");
 }
}
